insert into public.notes (id, data) values ('n1', '{"id":"n1","name":"Maria Schmidt","organisation":"Open Society Foundations","day":1,"time":"14:32","text":"The rights-based approaches session surfaced strong demand for a shared learning platform. OSF will follow up with MENA Rights Group on joint programming opportunities in the Mediterranean region."}'::jsonb) on conflict (id) do nothing;
insert into public.notes (id, data) values ('n2', '{"id":"n2","name":"James Odhiambo","organisation":"OAK Foundation","day":1,"time":"16:50","text":"Digital Rights breakout: participants want a working group to share tools for operating in restricted digital environments. Interested orgs: Digital Frontiers, Access Now, EFF."}'::jsonb) on conflict (id) do nothing;
insert into public.notes (id, data) values ('n3', '{"id":"n3","name":"Awa Diallo","organisation":"Geneva Secretariat","day":2,"time":"11:15","text":"Strategic communications workshop highly rated. Rashida’s adaptive messaging framework is directly applicable across 60% of the portfolio. Requesting follow-up toolkit."}'::jsonb) on conflict (id) do nothing;
insert into public.notes (id, data) values ('n4', '{"id":"n4","name":"Pierre-Alain Dubois","organisation":"Sciences Po Paris","day":2,"time":"15:00","text":"Fishbowl revealed consensus: philanthropy needs to accept longer time horizons (10+ years) and better share learning. Key ask: OAK to publish failure cases alongside success stories."}'::jsonb) on conflict (id) do nothing;
